package com.worksphere.config;
import com.worksphere.security.JwtAuthFilter; import org.springframework.context.annotation.*; import org.springframework.security.authentication.*; import org.springframework.http.HttpMethod; import org.springframework.security.config.annotation.authentication.configuration.AuthenticationConfiguration; import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.*;
@Configuration @EnableMethodSecurity public class SecurityConfig { private final JwtAuthFilter jwt; public SecurityConfig(JwtAuthFilter j){jwt=j;} @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();} @Bean AuthenticationManager authenticationManager(AuthenticationConfiguration c)throws Exception{return c.getAuthenticationManager();} @Bean SecurityFilterChain filterChain(HttpSecurity h)throws Exception{h.csrf(c->c.disable()).cors(c->{}).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/auth/**").permitAll().requestMatchers(HttpMethod.GET,"/api/jobs","/api/jobs/*").permitAll().requestMatchers("/api/admin/**").hasRole("ADMIN").anyRequest().authenticated()).addFilterBefore(jwt,org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter.class);return h.build();} }
